	MOVD  ip+24(FP), R23
	MOVD  anchor+32(FP), R24
	MOVWU rep1+64(FP), R25
	MOVWU rep2+68(FP), R26
	MOVD  ZR, nSeq+96(FP)
	MOVD  ZR, nLits+104(FP)
	MOVW  ZR, llType+120(FP)
	MOVW  ZR, llPos+124(FP)

main:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  finish
	MOVD ZR, L_MLEN
	MOVD $1, R0
	MOVD R0, L_OFFBASE          // repcode1ToOffBase
	ADD  $1, R23, R0
	MOVD R0, L_START

	// repcode at ip+1
	CBZW  R25, search0
	ADD   $1, R23, R0
	SUB   R25, R0, R0
	MOVWU (R22)(R0), R1
	ADD   $1, R23, R2
	MOVWU (R22)(R2), R2
	CMPW  R1, R2
	BNE   search0
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $5, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $5, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	MOVD  R17, L_MLEN
	MOVD  depth+72(FP), R0
	CBZ   R0, store

search0:
	MOVD R23, R0
	CALL ·hcSearch5(SB)
	TBNZ $63, R0, bad
	MOVD L_MLEN, R2
	CMP  R2, R0
	BLE  nobetter0
	MOVD R0, L_MLEN
	MOVD R23, L_START
	MOVD R1, L_OFFBASE

nobetter0:
	MOVD L_MLEN, R2
	CMP  $4, R2
	BGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	SUB  R24, R23, R0
	ASR  $8, R0                 // kSearchStrength
	ADD  $1, R0
	ADD  R0, R23
	CMP  $8, R0                 // kLazySkippingStep
	CSET HI, R1
	MOVW R1, P_SKIP
	B    main

found:
	MOVD depth+72(FP), R0
	CBZ  R0, catchup

lazy:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CBZW  R25, lsearch1
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch1
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch1
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17               // mlRep
	ADD   R17<<1, R17, R0       // gain2
	MOVD  L_MLEN, R1
	ADD   R1<<1, R1, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2                // highbit = 31 - clz
	ADD   R2, R1
	SUB   $30, R1               // gain1
	CMP   R1, R0
	BLE   lsearch1
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch1:
	MOVD R23, R0
	CALL ·hcSearch5(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $27, R4
	CMP   R4, R3
	BLE   ldepth2
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

ldepth2:
	MOVD depth+72(FP), R0
	CMP  $2, R0
	BNE  catchup
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CBZW  R25, lsearch2
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch2
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch2
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	LSL   $2, R17, R0
	MOVD  L_MLEN, R1
	LSL   $2, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2
	ADD   R2, R1
	SUB   $30, R1
	CMP   R1, R0
	BLE   lsearch2
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch2:
	MOVD R23, R0
	CALL ·hcSearch5(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $24, R4
	CMP   R4, R3
	BLE   catchup
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

catchup:
	MOVD L_OFFBASE, R0
	CMP  $3, R0
	BLS  store                  // a repcode: no catch up
	SUB  $3, R0                 // offset
	MOVD L_START, R1
	MOVD L_MLEN, R2
	MOVD prefixLowest+56(FP), R3

back:
	CMP   R24, R1
	BLE   backdone
	SUB   R0, R1, R4
	CMP   R3, R4
	BLE   backdone
	ADD   R1, R22, R5
	MOVBU -1(R5), R5
	ADD   R4, R22, R6
	MOVBU -1(R6), R6
	CMPW  R5, R6
	BNE   backdone
	SUB   $1, R1
	ADD   $1, R2
	B     back

backdone:
	MOVD  R1, L_START
	MOVD  R2, L_MLEN
	MOVD  R25, R26              // offset2 = offset1
	MOVWU R0, R25               // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVD L_START, R3
	SUB  R24, R3, R3
	MOVD L_OFFBASE, R7
	MOVD L_MLEN, R6
	MOVD ZR, R10
	B    storeseq

afterstore:
	MOVD  L_START, R0
	MOVD  L_MLEN, R1
	ADD   R1, R0, R23
	MOVD  R23, R24
	MOVWU P_SKIP, R0
	CBZW  R0, reploop
	// leave lazy skipping
	MOVW  ZR, P_SKIP

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVD  ilimit+48(FP), R0
	CMP   R0, R23
	BGT   main
	CBZW  R26, main
	SUB   R26, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   main
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17, R6           // matchLength
	MOVD  R26, R0               // swap repcodes
	MOVD  R25, R26
	MOVD  R0, R25
	MOVD  R6, L_MLEN
	MOVD  ZR, R3                // no literals
	MOVD  $1, R7                // repcode1ToOffBase
	MOVD  $1, R10
	B     storeseq

afterrep:
	MOVD L_MLEN, R0
	ADD  R0, R23
	MOVD R23, R24
	B    reploop

	// storeseq: R3 litLen (from anchor), R7 offBase, R6 matchLength;
	// returns to afterstore (R10 = 0) or afterrep (R10 = 1).
storeseq:
	CBZ  R3, seq
	MOVD lits+16(FP), R14
	MOVD nLits+104(FP), R17
	ADD  R17, R14
	ADD  R24, R22, R15
	MOVD R3, R16
	CALL ·fastCopyLits(SB)
	MOVD nLits+104(FP), R17
	ADD  R3, R17
	MOVD R17, nLits+104(FP)

seq:
	MOVD seqs+8(FP), R14
	MOVD nSeq+96(FP), R15
	ADD  R15<<3, R14, R14
	MOVW R7, (R14)
	MOVH R3, 4(R14)
	SUB  $3, R6, R16
	MOVH R16, 6(R14)
	CMP  $0xFFFF, R3
	BLS  nolongll
	MOVD $1, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongll:
	CMP  $0xFFFF, R16
	BLS  nolongml
	MOVD $2, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongml:
	ADD  $1, R15
	MOVD R15, nSeq+96(FP)
	CBZ  R10, afterstore
	B    afterrep

finish:
	MOVD R23, ipOut+80(FP)
	MOVD R24, anchorOut+88(FP)
	MOVW R25, rep1Out+112(FP)
	MOVW R26, rep2Out+116(FP)
	RET

bad:
	MOVD $-1, R0
	MOVD R0, nSeq+96(FP)
	RET

// hcSearch6: hcFindBestMatch (noDict, mls 6) at R0 = ip, R21 = p,
// with insertAndFindFirstIndexInternal. Returns R0 = ml (below 4: none; -1:
// a chain entry at or after ip, impossible), R1 = offBase. Clobbers R0-R17,
// R19, R20.
TEXT ·hcSearch6(SB), NOSPLIT|NOFRAME, $0-0
	MOVD  P_B, R4
	MOVWU P_BASEIDX, R5
	SUB   R5, R4, R4            // b - baseIdx (no calls: never seen by the GC)
	ADDW  R0, R5, R5            // curr
	MOVD  P_HASHTABLE, R6
	MOVD  P_CHAIN, R7
	MOVWU P_CHAINMASK, R8
	MOVD  $0xCF1BBCDCBF9B0000, R9
	MOVD  P_HSHIFT, R10

	// insert [nextToUpdate, curr), or only nextToUpdate when lazy skipping
	// (C: ZSTD_insertAndFindFirstIndex_internal); see the amd64 generator
	// for the bounds.
	MOVD  P_NEXT, R11
	MOVWU (R11), R2
	MOVWU R5, R3                // the insert limit
	MOVWU P_SKIP, R12
	CBZW  R12, insck
	ADDW  $1, R2, R3
	CMPW  R5, R3
	CSELW HI, R5, R3, R3
	B     insck

ins:
	MOVD  (R4)(R2), R11
	MUL   R9, R11, R11
	LSR   R10, R11, R11
	MOVWU (R6)(R11<<2), R12
	ANDW  R8, R2, R13
	MOVW  R12, (R7)(R13<<2)     // C: NEXT_IN_CHAIN(idx, chainMask) = hashTable[h]
	MOVW  R2, (R6)(R11<<2)
	ADDW  $1, R2

insck:
	CMPW  R3, R2
	BLO   ins
	MOVD  P_NEXT, R11
	MOVW  R5, (R11)             // nextToUpdate = curr
	MOVD  (R4)(R5), R11
	MUL   R9, R11, R11
	LSR   R10, R11, R11
	MOVWU (R6)(R11<<2), R2      // matchIndex

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVWU P_LOWEST, R12
	MOVWU P_MAXDIST, R13
	SUBW  R12, R5, R11
	CMPW  R13, R11
	BLS   lowok
	SUBW  R13, R5, R12

lowok:
	MOVWU P_ISDICT, R11
	CBZW  R11, lowset
	MOVWU P_LOWEST, R12

lowset:
	// minChain = curr > chainSize ? curr - chainSize : 0
	ADDW  $1, R8, R11
	SUBSW R11, R5, R13
	CSELW HI, R13, ZR, R13
	MOVWU P_ATTEMPTS, R14
	MOVD  P_ILIMIT, R16
	SUB   R0, R16, R16          // iLimit - ip
	MOVD  P_B, R15
	ADD   R0, R15, R15          // ip
	MOVD  $3, R17               // ml
	MOVD  ZR, R20               // best matchIndex
	MOVWU (R15), R19            // read32(ip + ml - 3)

walk:
	CMPW  R12, R2
	BLO   done                  // below lowLimit
	// lowLimit <= R2 < curr and lowLimit >= baseIdx (see the amd64
	// generator), so R4 + R2 lies in b[0:ip].
	CMPW  R5, R2
	BHS   bad
	ADD   R2, R4, R11           // match
	ADD   R17, R11, R0
	MOVWU -3(R0), R0
	CMPW  R0, R19
	BNE   next
	MOVD  ZR, R3

cnt8:
	ADD  $8, R3, R0
	CMP  R16, R0
	BHI  cnttail
	MOVD (R11)(R3), R0
	MOVD (R15)(R3), R1
	EOR  R0, R1, R1
	CBNZ R1, cntdiff
	ADD  $8, R3
	B    cnt8

cntdiff:
	RBIT R1, R1
	CLZ  R1, R1
	ADD  R1>>3, R3, R3
	B    cntdone

cnttail:
	CMP   R16, R3
	BHS   cntdone
	MOVBU (R11)(R3), R0
	MOVBU (R15)(R3), R1
	CMPW  R0, R1
	BNE   cntdone
	ADD   $1, R3
	B     cnttail

cntdone:
	CMP   R17, R3
	BLE   next
	MOVD  R3, R17               // a longer match
	MOVWU R2, R20
	CMP   R16, R3
	BEQ   done                  // best possible, avoids read overflow on next attempt
	ADD   R17, R15, R0
	MOVWU -3(R0), R19

next:
	CMPW  R13, R2
	BLS   done                  // matchIndex <= minChain
	ANDW  R8, R2, R2
	MOVWU (R7)(R2<<2), R2       // C: NEXT_IN_CHAIN(matchIndex, chainMask)
	SUBSW $1, R14
	BNE   walk

done:
	MOVD R17, R0
	MOVD $999999999, R1         // offBaseNotFound
	CMP  $3, R17
	BLE  ret
	SUBW R20, R5, R1
	ADDW $3, R1                 // offsetToOffBase(curr - matchIndex)

ret:
	RET

bad:
	MOVD $-1, R0
	RET

// func lazyHc6(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, hash chain) for mls 6: compressBlockLazyGeneric's match loop. R21 p, R22 b, R23 ip,
// R24 anchor, R25 offset1, R26 offset2; start, mLength and offBase live in
// the frame, nSeq and nLits in their result slots. nSeq = -1 reports a
// table entry at or after the position searched (impossible).
TEXT ·lazyHc6(SB), NOSPLIT, $32-128
	MOVD  p+0(FP), R21
	MOVD  P_B, R22
	MOVD  ip+24(FP), R23
	MOVD  anchor+32(FP), R24
	MOVWU rep1+64(FP), R25
	MOVWU rep2+68(FP), R26
	MOVD  ZR, nSeq+96(FP)
	MOVD  ZR, nLits+104(FP)
	MOVW  ZR, llType+120(FP)
	MOVW  ZR, llPos+124(FP)

main:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  finish
	MOVD ZR, L_MLEN
	MOVD $1, R0
	MOVD R0, L_OFFBASE          // repcode1ToOffBase
	ADD  $1, R23, R0
	MOVD R0, L_START

	// repcode at ip+1
	CBZW  R25, search0
	ADD   $1, R23, R0
	SUB   R25, R0, R0
	MOVWU (R22)(R0), R1
	ADD   $1, R23, R2
	MOVWU (R22)(R2), R2
	CMPW  R1, R2
	BNE   search0
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $5, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $5, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	MOVD  R17, L_MLEN
	MOVD  depth+72(FP), R0
	CBZ   R0, store

search0:
	MOVD R23, R0
	CALL ·hcSearch6(SB)
	TBNZ $63, R0, bad
	MOVD L_MLEN, R2
	CMP  R2, R0
	BLE  nobetter0
	MOVD R0, L_MLEN
	MOVD R23, L_START
	MOVD R1, L_OFFBASE

nobetter0:
	MOVD L_MLEN, R2
	CMP  $4, R2
	BGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	SUB  R24, R23, R0
	ASR  $8, R0                 // kSearchStrength
	ADD  $1, R0
	ADD  R0, R23
	CMP  $8, R0                 // kLazySkippingStep
	CSET HI, R1
	MOVW R1, P_SKIP
	B    main

found:
	MOVD depth+72(FP), R0
	CBZ  R0, catchup

lazy:
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	CBZW  R25, lsearch1
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch1
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch1
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17               // mlRep
	ADD   R17<<1, R17, R0       // gain2
	MOVD  L_MLEN, R1
	ADD   R1<<1, R1, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2                // highbit = 31 - clz
	ADD   R2, R1
	SUB   $30, R1               // gain1
	CMP   R1, R0
	BLE   lsearch1
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch1:
	MOVD R23, R0
	CALL ·hcSearch6(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $27, R4
	CMP   R4, R3
	BLE   ldepth2
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

ldepth2:
	MOVD depth+72(FP), R0
	CMP  $2, R0
	BNE  catchup
	MOVD ilimit+48(FP), R0
	CMP  R0, R23
	BGE  catchup
	ADD  $1, R23
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	CBZW  R25, lsearch2
	MOVD  L_OFFBASE, R0
	CBZ   R0, lsearch2
	SUB   R25, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   lsearch2
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17
	LSL   $2, R17, R0
	MOVD  L_MLEN, R1
	LSL   $2, R1
	MOVWU L_OFFBASE, R2
	CLZW  R2, R2
	ADD   R2, R1
	SUB   $30, R1
	CMP   R1, R0
	BLE   lsearch2
	MOVD  R17, L_MLEN
	MOVD  $1, R0
	MOVD  R0, L_OFFBASE
	MOVD  R23, L_START

lsearch2:
	MOVD R23, R0
	CALL ·hcSearch6(SB)
	TBNZ $63, R0, bad
	CMP  $4, R0
	BLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	CLZW  R1, R2
	LSL   $2, R0, R3
	ADD   R2, R3
	SUB   $31, R3
	MOVD  L_MLEN, R4
	LSL   $2, R4
	MOVWU L_OFFBASE, R5
	CLZW  R5, R5
	ADD   R5, R4
	SUB   $24, R4
	CMP   R4, R3
	BLE   catchup
	MOVD  R0, L_MLEN
	MOVD  R1, L_OFFBASE
	MOVD  R23, L_START
	B     lazy

catchup:
	MOVD L_OFFBASE, R0
	CMP  $3, R0
	BLS  store                  // a repcode: no catch up
	SUB  $3, R0                 // offset
	MOVD L_START, R1
	MOVD L_MLEN, R2
	MOVD prefixLowest+56(FP), R3

back:
	CMP   R24, R1
	BLE   backdone
	SUB   R0, R1, R4
	CMP   R3, R4
	BLE   backdone
	ADD   R1, R22, R5
	MOVBU -1(R5), R5
	ADD   R4, R22, R6
	MOVBU -1(R6), R6
	CMPW  R5, R6
	BNE   backdone
	SUB   $1, R1
	ADD   $1, R2
	B     back

backdone:
	MOVD  R1, L_START
	MOVD  R2, L_MLEN
	MOVD  R25, R26              // offset2 = offset1
	MOVWU R0, R25               // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVD L_START, R3
	SUB  R24, R3, R3
	MOVD L_OFFBASE, R7
	MOVD L_MLEN, R6
	MOVD ZR, R10
	B    storeseq

afterstore:
	MOVD  L_START, R0
	MOVD  L_MLEN, R1
	ADD   R1, R0, R23
	MOVD  R23, R24
	MOVWU P_SKIP, R0
	CBZW  R0, reploop
	// leave lazy skipping
	MOVW  ZR, P_SKIP

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVD  ilimit+48(FP), R0
	CMP   R0, R23
	BGT   main
	CBZW  R26, main
	SUB   R26, R23, R0
	MOVWU (R22)(R0), R1
	MOVWU (R22)(R23), R2
	CMPW  R1, R2
	BNE   main
	ADD   R0, R22, R15
	ADD   $4, R15
	ADD   R23, R22, R14
	ADD   $4, R14
	MOVD  iend+40(FP), R16
	SUB   R23, R16, R16
	SUB   $4, R16
	CALL  ·fastCount(SB)
	ADD   $4, R17, R6           // matchLength
	MOVD  R26, R0               // swap repcodes
	MOVD  R25, R26
	MOVD  R0, R25
	MOVD  R6, L_MLEN
	MOVD  ZR, R3                // no literals
	MOVD  $1, R7                // repcode1ToOffBase
	MOVD  $1, R10
	B     storeseq

afterrep:
	MOVD L_MLEN, R0
	ADD  R0, R23
	MOVD R23, R24
	B    reploop

	// storeseq: R3 litLen (from anchor), R7 offBase, R6 matchLength;
	// returns to afterstore (R10 = 0) or afterrep (R10 = 1).
storeseq:
	CBZ  R3, seq
	MOVD lits+16(FP), R14
	MOVD nLits+104(FP), R17
	ADD  R17, R14
	ADD  R24, R22, R15
	MOVD R3, R16
	CALL ·fastCopyLits(SB)
	MOVD nLits+104(FP), R17
	ADD  R3, R17
	MOVD R17, nLits+104(FP)

seq:
	MOVD seqs+8(FP), R14
	MOVD nSeq+96(FP), R15
	ADD  R15<<3, R14, R14
	MOVW R7, (R14)
	MOVH R3, 4(R14)
	SUB  $3, R6, R16
	MOVH R16, 6(R14)
	CMP  $0xFFFF, R3
	BLS  nolongll
	MOVD $1, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongll:
	CMP  $0xFFFF, R16
	BLS  nolongml
	MOVD $2, R17
	MOVW R17, llType+120(FP)
	MOVW R15, llPos+124(FP)

nolongml:
	ADD  $1, R15
	MOVD R15, nSeq+96(FP)
	CBZ  R10, afterstore
	B    afterrep

finish:
	MOVD R23, ipOut+80(FP)
	MOVD R24, anchorOut+88(FP)
	MOVW R25, rep1Out+112(FP)
	MOVW R26, rep2Out+116(FP)
	RET

bad:
	MOVD $-1, R0
	MOVD R0, nSeq+96(FP)
	RET
